// ============================================================================
// fluid_case.hpp
//
// The fluid-core manufactured problem of fields_fluid.hpp (generated by
// manufacture_fluid.py; its docstring holds the weak form and every
// source) set up, solved and measured on a two-layer ball, serial or
// parallel: shared by the driver manufactured_fluid_benchmark and the
// test tests/TestManufacturedFluid.cpp.
//
// Mesh conventions (meshes/layered_earth.py --layers 2 --dim 3): domain
// attributes 1 fluid core, 2 solid shell, 3 buffer; boundary attributes
// 1 CMB (interior), 2 surface, 3 outer sphere. The displacement lives on
// the SubMesh of attribute 2, which keeps the boundary attributes 1
// (CMB) and 2 (surface).
//
// The problem: LinearQuasiStaticMixedSelfGravitatingProblem with the
// exact background potential (the analytic Phi0 of the layered density),
// the core as a FluidRegion (density, d rho / d Phi0 and bulk modulus of
// the header) and the level border (SetLevelBorder), with every load of
// the header applied:
//   displacement row  the body force on the shell, the traction on the
//                     surface and the CMB traction (with the buoyancy, the
//                     potential stress and the wall pressure),
//   potential row     the volume sources of the core and the shell (none
//                     in the buffer), the flux sources on the surface and
//                     on the CMB,
//   border rows       the U, s and nu rows' data integrated against the
//                     border's own hat functions, and the wall row's.
// The surface data are evaluated with the facet's own unit normal (the
// discrete boundary's), oriented by the sign of n.x: the solid's outward
// normal, +x/r-like on the surface and -x/r-like on the CMB, on the
// SubMesh and on the parent alike (the parent's interior boundary
// elements carry an arbitrary orientation).
//
// The measures. The solver's gauge removes the rigid modes from the
// displacement; the exact one carries a rigid part, so the rigid part of
// u_h - u* is fitted on the discrete rigid modes (true-dof inner
// product) and removed, and the potential is compared with
// phi* - r.grad Phi0 over the whole ball (the null pair's partner; the
// border unknowns of a rigid motion vanish). Reported, relative: the L2
// errors of u and of the stress over the shell, of phi over the whole
// computational domain and over the core alone; the border's nodal U, s,
// nu against U*, s*, nu* at the grid's nodes (largest error over the
// largest exact value, the RMS ratio, and the volume-weighted L2 error
// over the core), and the wall multiplier. Diagnostics: the border rows'
// residual at the exact solution, the deviation of the border's element
// volumes (binned fluid quadrature points) from the analytic shells, and
// the orientation of the boundary elements' own normals.
// ============================================================================

#pragma once

#include <algorithm>
#include <chrono>
#include <cmath>
#include <functional>
#include <memory>
#include <vector>

#include "AdGIA/detail/fem_factory.hpp"
#include "AdGIA/mixed_problem.hpp"
#include "AdGIA/rheology.hpp"
#include "fields_fluid.hpp"
#include "mfem.hpp"

namespace manufactured_fluid {

using namespace mfem;

constexpr int kCoreAttr = 1, kShellAttr = 2;  // domain attributes
constexpr int kCmbBdr = 1, kSurfaceBdr = 2;   // boundary attributes

// The assembly of the gravity term (as the solid family's drivers).
enum class Gravity {
  Default,       // the class default: the Hessian of the discrete Phi0
  ExactHessian,  // SetBackgroundHessian with the analytic Hessian
  Interpolant    // SetBackgroundHessian(nullptr): the nodal interpolant
};

struct Options {
  int levels = 16;             // nodes of the border's level grid
  bool exact_levels = true;    // the border reads the analytic Phi0
  Gravity gravity = Gravity::Default;
  double rel_tol = 1e-11;
  int dtn_degree = 12;
  bool border_sources = true;  // the border rows' data (sensitivity: off)
  bool cmb_traction = true;    // the CMB traction (sensitivity: off)
  bool strong_border = false;  // U row data from r_U and R_w (same data)
  bool sphere_normal = false;  // x/|x| for the surface data, not the facet's
};

struct Results {
  double u = 0, stress = 0, phi = 0, phi_core = 0, rigid = 0;
  double U_max = 0, U_rms = 0, s_max = 0, s_rms = 0, nu_max = 0,
         nu_rms = 0, lambda = 0, lambda_h = 0;
  // The border functions' volume-weighted L2 errors over the core,
  // int_F (v_h(Phi0) - v*)^2 dV = int A (v_h - v*)^2 dc, relative.
  double U_vol = 0, s_vol = 0, nu_vol = 0;
  double c_lo = 0, c_hi = 0;  // the grid's end levels
  int iterations = 0;
  double solve_seconds = 0;
  long dofs_u = 0, dofs_phi = 0;
  // SubMesh CMB / surface facets whose CalcOrtho normal points against
  // the solid's outward normal, and the parent's CMB facets whose normal
  // points away from the centre (global counts out of the totals).
  long flipped_cmb = 0, flipped_surface = 0, parent_cmb_up = 0;
  long facets_cmb = 0, facets_surface = 0;
  // The border rows' residual at the exact solution's interpolant,
  // |D_b y* + B^T x* - r| over |r| per row group (U, s, nu, wall): the
  // consistency of the data with the assembled border.
  double res_U = 0, res_s = 0, res_nu = 0, res_lambda = 0;
  // The border's element volumes (binned fluid quadrature points)
  // against the analytic shells between the nodes' radii: the largest
  // and the RMS relative deviation.
  double vol_max = 0, vol_rms = 0;
  // The border solution at the grid's nodes.
  Vector c, U, s, nu;
};

// --- parallel-neutral helpers ----------------------------------------------

inline void SumOver(const FiniteElementSpace& fes, double* v, int n) {
#ifdef MFEM_USE_MPI
  if (auto* p = dynamic_cast<const ParFiniteElementSpace*>(&fes)) {
    MPI_Allreduce(MPI_IN_PLACE, v, n, MPI_DOUBLE, MPI_SUM, p->GetComm());
  }
#else
  (void)fes;
  (void)v;
  (void)n;
#endif
}

inline double Dot(const FiniteElementSpace& fes, const Vector& a,
                  const Vector& b) {
  double v = a * b;  // true dofs: disjoint across ranks
  SumOver(fes, &v, 1);
  return v;
}

inline long GlobalTrueSize(FiniteElementSpace& fes) {
  double v = fes.GetTrueVSize();
  SumOver(fes, &v, 1);
  return static_cast<long>(v);
}

// --- surface data ----------------------------------------------------------

// The unit normal of a boundary element at ip, oriented so that
// sign * (n . x) > 0 (sign +1: away from the centre, the solid's outward
// normal on the surface; -1: towards it, the solid's outward normal on
// the CMB); with `sphere`, sign x/|x| instead of the facet's normal.
inline void OrientedNormal(ElementTransformation& T, const IntegrationPoint& ip,
                           const Vector& x, double sign, bool sphere,
                           Vector& n) {
  n.SetSize(x.Size());
  if (sphere) {
    n = x;
    n *= sign / x.Norml2();
    return;
  }
  T.SetIntPoint(&ip);
  CalcOrtho(T.Jacobian(), n);
  n /= n.Norml2();
  if (sign * (n * x) < 0.0) {
    n.Neg();
  }
}

class FacetVectorCoefficient : public VectorCoefficient {
 public:
  using Fn = void (*)(const double*, const double*, double*);
  FacetVectorCoefficient(Fn f, double sign, bool sphere)
      : VectorCoefficient(3), f_(f), sign_(sign), sphere_(sphere) {}
  void Eval(Vector& V, ElementTransformation& T,
            const IntegrationPoint& ip) override {
    T.Transform(ip, x_);
    OrientedNormal(T, ip, x_, sign_, sphere_, n_);
    V.SetSize(3);
    f_(x_.GetData(), n_.GetData(), V.GetData());
  }

 private:
  Fn f_;
  double sign_;
  bool sphere_;
  Vector x_, n_;
};

class FacetCoefficient : public Coefficient {
 public:
  using Fn = double (*)(const double*, const double*);
  FacetCoefficient(Fn f, double sign, bool sphere)
      : f_(f), sign_(sign), sphere_(sphere) {}
  double Eval(ElementTransformation& T, const IntegrationPoint& ip) override {
    T.Transform(ip, x_);
    OrientedNormal(T, ip, x_, sign_, sphere_, n_);
    return f_(x_.GetData(), n_.GetData());
  }

 private:
  Fn f_;
  double sign_;
  bool sphere_;
  Vector x_, n_;
};

// Facets of boundary attribute `attr` whose CalcOrtho normal at the
// centre has sign * (n . x) < 0, and their number (local counts).
inline void CountFlipped(Mesh& mesh, int attr, double sign, long& flipped,
                         long& total) {
  flipped = total = 0;
  Vector x, n;
  for (int be = 0; be < mesh.GetNBE(); be++) {
    if (mesh.GetBdrAttribute(be) != attr) {
      continue;
    }
    ElementTransformation& T = *mesh.GetBdrElementTransformation(be);
    const IntegrationPoint& ip =
        Geometries.GetCenter(mesh.GetBdrElementGeometry(be));
    T.SetIntPoint(&ip);
    T.Transform(ip, x);
    n.SetSize(x.Size());
    CalcOrtho(T.Jacobian(), n);
    total++;
    flipped += sign * (n * x) < 0.0 ? 1 : 0;
  }
}

// --- exact fields by region ------------------------------------------------

// A rigid motion r(x) = a + b x x.
struct Rigid {
  double a[3] = {0, 0, 0}, b[3] = {0, 0, 0};
  void At(const double* x, double* r) const {
    r[0] = a[0] + b[1] * x[2] - b[2] * x[1];
    r[1] = a[1] + b[2] * x[0] - b[0] * x[2];
    r[2] = a[2] + b[0] * x[1] - b[1] * x[0];
  }
};

// phi* - r.grad Phi0 by element attribute (the discrete regions; phi*
// and grad Phi0 per region of the header).
class ExactPotential : public Coefficient {
 public:
  explicit ExactPotential(const Rigid& r) : r_(r) {}
  double Eval(ElementTransformation& T, const IntegrationPoint& ip) override {
    T.Transform(ip, x_);
    const double* x = x_.GetData();
    double g[3], rv[3], p;
    if (T.Attribute == kCoreAttr) {
      p = d3::phi_core(x);
      d3::grad_phi0_core(x, g);
    } else if (T.Attribute == kShellAttr) {
      p = d3::phi_shell(x);
      d3::grad_phi0_shell(x, g);
    } else {
      p = d3::phi_out(x);
      d3::grad_phi0_out(x, g);
    }
    r_.At(x, rv);
    return p - (rv[0] * g[0] + rv[1] * g[1] + rv[2] * g[2]);
  }

 private:
  const Rigid& r_;
  Vector x_;
};

// --- the border data -------------------------------------------------------

struct BorderData {
  Vector rU, rs, rnu, rlambda;
};

// The border rows' data on the grid c (the class's, LevelBorderGrid()):
//   rU[i]  = int N_i' (kappa U*'/A + rho s*) dc + int N_i nu* dc
//            + lambda* N_i(c_w)                (the weak residual), or
//            int N_i r_U dc + R_w at the wall node (`strong`; the same),
//   rs[i]  = int N_i r_s dc,   rnu[i] = int N_i r_nu dc,
//   rlambda = U*(c_w) - S[u*].
// The integrals run over the exact core [c_min, c_w] with the hats
// clamped beyond the grid's end nodes (N_0 = 1 below c_0, N_n = 1 above
// c_n, as the class locates the levels of its fluid quadrature points),
// per interval IN r between the radii of the nodes, dc = g(r) dr, by
// 20-point Gauss-Legendre: the integrands are smooth in r, while in c
// they behave like sqrt(c - c_min) at the centre.
inline BorderData IntegrateBorderData(const Vector& c, bool strong) {
  const int n = c.Size() - 1;
  BorderData d;
  d.rU.SetSize(n + 1);
  d.rs.SetSize(n + 1);
  d.rnu.SetSize(n + 1);
  d.rU = 0.0;
  d.rs = 0.0;
  d.rnu = 0.0;
  std::vector<double> rb = {0.0, d3::level_radius(kCWall)};
  for (int k = 0; k <= n; k++) {
    rb.push_back(d3::level_radius(c[k]));
  }
  std::sort(rb.begin(), rb.end());
  const IntegrationRule& ir = IntRules.Get(Geometry::SEGMENT, 39);
  for (size_t i = 0; i + 1 < rb.size(); i++) {
    const double r0 = rb[i], r1 = rb[i + 1];
    if (r1 - r0 <= 1e-14) {
      continue;
    }
    // The grid element of this interval (-1 below the grid, n above).
    const double cm = d3::level_value(0.5 * (r0 + r1));
    int e = -1;
    if (cm >= c[n]) {
      e = n;
    } else if (cm >= c[0]) {
      e = 0;
      while (e < n - 1 && cm > c[e + 1]) {
        e++;
      }
    }
    for (int q = 0; q < ir.GetNPoints(); q++) {
      const IntegrationPoint& ip = ir.IntPoint(q);
      const double r = r0 + (r1 - r0) * ip.x;
      const double w = ip.weight * (r1 - r0) * d3::level_gravity(r);  // dc
      const double cv = d3::level_value(r);
      // The two hats on the interval, their nodes and derivatives.
      int i0, i1;
      double N0, N1, D0, D1;
      if (e < 0 || e == n) {
        i0 = i1 = (e < 0) ? 0 : n;
        N0 = 1.0;
        N1 = 0.0;
        D0 = D1 = 0.0;
      } else {
        const double h = c[e + 1] - c[e];
        i0 = e;
        i1 = e + 1;
        N1 = (cv - c[e]) / h;
        N0 = 1.0 - N1;
        D0 = -1.0 / h;
        D1 = 1.0 / h;
      }
      const double qs = d3::border_s_source_r(r) * w;
      const double qnu = d3::border_nu_source_r(r) * w;
      d.rs[i0] += N0 * qs;
      d.rs[i1] += N1 * qs;
      d.rnu[i0] += N0 * qnu;
      d.rnu[i1] += N1 * qnu;
      if (strong) {
        const double qU = d3::border_U_source_r(r) * w;
        d.rU[i0] += N0 * qU;
        d.rU[i1] += N1 * qU;
      } else {
        const double flux = d3::border_U_flux_r(r) * w;
        const double nu = d3::border_nu_r(r) * w;
        d.rU[i0] += D0 * flux + N0 * nu;
        d.rU[i1] += D1 * flux + N1 * nu;
      }
    }
  }
  d.rU[n] += strong ? kBorderUWall : kLambda;
  d.rlambda.SetSize(1);
  d.rlambda[0] = kBorderLambdaSource;
  return d;
}

// --- error measures --------------------------------------------------------

// int (f_h - f*)^2 and int f*^2 over the elements of attribute `attr`
// (0: all), global.
inline void ScalarL2(const GridFunction& fh, Coefficient& ex, int attr,
                     int qorder, double out[2]) {
  Mesh& mesh = *fh.FESpace()->GetMesh();
  out[0] = out[1] = 0.0;
  for (int e = 0; e < mesh.GetNE(); e++) {
    if (attr && mesh.GetAttribute(e) != attr) {
      continue;
    }
    ElementTransformation& T = *mesh.GetElementTransformation(e);
    const IntegrationRule& ir = IntRules.Get(mesh.GetElementGeometry(e), qorder);
    for (int q = 0; q < ir.GetNPoints(); q++) {
      const IntegrationPoint& ip = ir.IntPoint(q);
      T.SetIntPoint(&ip);
      const double v = fh.GetValue(T, ip), ve = ex.Eval(T, ip);
      const double w = ip.weight * T.Weight();
      out[0] += w * (v - ve) * (v - ve);
      out[1] += w * ve * ve;
    }
  }
  SumOver(*fh.FESpace(), out, 2);
}

// Relative L2 errors of the displacement and of the stress sigma(u) over
// the shell, against u* and sigma(u*) of the header.
inline void ShellErrors(const GridFunction& u, int qorder, double& u_err,
                        double& stress_err) {
  Mesh& mesh = *u.FESpace()->GetMesh();
  double v[4] = {0, 0, 0, 0};
  Vector x, uh(3);
  DenseMatrix grad(3);
  double us[3], sig_ex[9];
  for (int e = 0; e < mesh.GetNE(); e++) {
    ElementTransformation& T = *mesh.GetElementTransformation(e);
    const IntegrationRule& ir = IntRules.Get(mesh.GetElementGeometry(e), qorder);
    for (int q = 0; q < ir.GetNPoints(); q++) {
      const IntegrationPoint& ip = ir.IntPoint(q);
      T.SetIntPoint(&ip);
      T.Transform(ip, x);
      const double w = ip.weight * T.Weight();
      u.GetVectorValue(T, ip, uh);
      d3::u(x.GetData(), us);
      for (int i = 0; i < 3; i++) {
        v[0] += w * (uh[i] - us[i]) * (uh[i] - us[i]);
        v[1] += w * us[i] * us[i];
      }
      u.GetVectorGradient(T, grad);
      const double kappa = d3::kappa(x.GetData()), mu = d3::mu(x.GetData());
      const double divu = grad(0, 0) + grad(1, 1) + grad(2, 2);
      d3::stress(x.GetData(), sig_ex);
      for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
          const double eps = 0.5 * (grad(i, j) + grad(j, i));
          const double sig = 2.0 * mu * (eps - (i == j ? divu / 3.0 : 0.0)) +
                             (i == j ? kappa * divu : 0.0);
          const double d = sig - sig_ex[3 * i + j];  // row-major
          v[2] += w * d * d;
          v[3] += w * sig_ex[3 * i + j] * sig_ex[3 * i + j];
        }
      }
    }
  }
  SumOver(*u.FESpace(), v, 4);
  u_err = std::sqrt(v[0] / v[1]);
  stress_err = std::sqrt(v[2] / v[3]);
}

// Nodal errors of a border function against the exact one at the nodes:
// the largest error over the largest exact value, and the RMS ratio.
inline void NodalErrors(const Vector& c, const Vector& vh,
                        double (*exact)(double), double& max_rel,
                        double& rms_rel) {
  double emax = 0.0, xmax = 0.0, e2 = 0.0, x2 = 0.0;
  for (int k = 0; k < c.Size(); k++) {
    const double xe = exact(c[k]), d = vh[k] - xe;
    emax = std::max(emax, std::abs(d));
    xmax = std::max(xmax, std::abs(xe));
    e2 += d * d;
    x2 += xe * xe;
  }
  max_rel = emax / xmax;
  rms_rel = std::sqrt(e2 / x2);
}

// The volume-weighted relative L2 error of a border function, P1 in c on
// the grid c with the nodal values vh (constant beyond the end nodes):
// int A (v_h - v*)^2 dc over int A v*^2 dc on the exact core, integrated
// in r (A dc = 4 pi r^2 dr) per interval between the nodes' radii.
inline double VolumeWeightedError(const Vector& c, const Vector& vh,
                                  double (*exact_r)(double)) {
  const int n = c.Size() - 1;
  std::vector<double> rb = {0.0, d3::level_radius(kCWall)};
  for (int k = 0; k <= n; k++) {
    rb.push_back(d3::level_radius(c[k]));
  }
  std::sort(rb.begin(), rb.end());
  const IntegrationRule& ir = IntRules.Get(Geometry::SEGMENT, 39);
  double num = 0.0, den = 0.0;
  for (size_t i = 0; i + 1 < rb.size(); i++) {
    const double r0 = rb[i], r1 = rb[i + 1];
    if (r1 - r0 <= 1e-14) {
      continue;
    }
    for (int q = 0; q < ir.GetNPoints(); q++) {
      const IntegrationPoint& ip = ir.IntPoint(q);
      const double r = r0 + (r1 - r0) * ip.x;
      const double w = ip.weight * (r1 - r0) * 4.0 * M_PI * r * r;
      const double cv = std::min(std::max(d3::level_value(r), c[0]), c[n]);
      int e = 0;
      while (e < n - 1 && cv > c[e + 1]) {
        e++;
      }
      const double t = (cv - c[e]) / (c[e + 1] - c[e]);
      const double v = (1.0 - t) * vh[e] + t * vh[e + 1], ve = exact_r(r);
      num += w * (v - ve) * (v - ve);
      den += w * ve * ve;
    }
  }
  return std::sqrt(num / den);
}

// --- the solve -------------------------------------------------------------

// Set up the problem on the spaces (fes_u on the shell SubMesh, fes_phi
// on the parent; parallel or serial), apply the loads, solve, measure.
inline Results Solve(FiniteElementSpace& fes_u, FiniteElementSpace& fes_phi,
                     const Options& opt) {
  using Clock = std::chrono::steady_clock;
  using AdGIA::detail::MakeGridFunction;
  using AdGIA::detail::MakeLinearForm;
  Mesh& solid = *fes_u.GetMesh();
  Mesh& parent = *fes_phi.GetMesh();
  MFEM_VERIFY(solid.Dimension() == 3, "three dimensions");
  MFEM_VERIFY(parent.attributes.Max() >= 3 && parent.bdr_attributes.Max() >= 2,
              "a two-layer ball in a buffer (attributes 1 core, 2 shell, "
              "3 buffer; boundary attributes 1 CMB, 2 surface)");
  const int order = fes_u.GetMaxElementOrder();
  const int order_phi = fes_phi.GetMaxElementOrder();

  // The background and the material.
  FunctionCoefficient phi0([](const Vector& x) { return d3::phi0(x.GetData()); });
  VectorFunctionCoefficient grad_phi0(3, [](const Vector& x, Vector& g) {
    g.SetSize(3);
    d3::grad_phi0(x.GetData(), g.GetData());
  });
  FunctionCoefficient rho_s([](const Vector& x) { return d3::rho_shell(x.GetData()); });
  FunctionCoefficient rho_f([](const Vector& x) { return d3::rho_core(x.GetData()); });
  FunctionCoefficient rho_fp([](const Vector& x) {
    return d3::rho_prime_fluid(x.GetData());
  });
  FunctionCoefficient kappa_f([](const Vector& x) {
    return d3::kappa_fluid(x.GetData());
  });
  FunctionCoefficient kappa([](const Vector& x) { return d3::kappa(x.GetData()); });
  FunctionCoefficient mu([](const Vector& x) { return d3::mu(x.GetData()); });
  // The shell's Hessian of Phi0 (the gravity term lives on the solid).
  MatrixFunctionCoefficient hess(3, [](const Vector& x, DenseMatrix& H) {
    double flat[9];
    d3::hess_phi0_shell(x.GetData(), flat);
    H.SetSize(3);
    for (int i = 0; i < 3; i++) {
      for (int j = 0; j < 3; j++) {
        H(i, j) = flat[3 * i + j];
      }
    }
  });
  AdGIA::IsotropicElasticRheology rheology(3, kappa, mu);
  AdGIA::FluidRegion core;
  core.attributes = Array<int>({kCoreAttr});
  core.density = &rho_f;
  core.density_gradient = &rho_fp;
  core.interface_marker.SetSize(solid.bdr_attributes.Max());
  core.interface_marker = 0;
  core.interface_marker[kCmbBdr - 1] = 1;
  core.bulk_modulus = &kappa_f;
  AdGIA::LinearQuasiStaticMixedSelfGravitatingProblem problem(
      &fes_u, &fes_phi, rheology, rho_s, kG, opt.dtn_degree, &phi0,
      {core});
  problem.SetRelTol(opt.rel_tol);
  if (opt.gravity == Gravity::ExactHessian) {
    problem.SetBackgroundHessian(&hess);
  } else if (opt.gravity == Gravity::Interpolant) {
    problem.SetBackgroundHessian(nullptr);
  }
  problem.SetLevelBorder(opt.levels, opt.exact_levels,
                         opt.exact_levels ? &grad_phi0 : nullptr);

  // The displacement row: body force, surface traction, CMB traction.
  const int qu = 2 * order + 4;
  const IntegrationRule& ir_vol = IntRules.Get(Geometry::TETRAHEDRON, qu);
  const IntegrationRule& ir_bdr = IntRules.Get(Geometry::TRIANGLE, qu);
  VectorFunctionCoefficient f(3, [](const Vector& x, Vector& v) {
    v.SetSize(3);
    d3::body_force(x.GetData(), v.GetData());
  });
  FacetVectorCoefficient t_surf(d3::traction_surface, +1.0, opt.sphere_normal);
  FacetVectorCoefficient t_cmb(d3::traction_cmb, -1.0, opt.sphere_normal);
  Array<int> s_surf(solid.bdr_attributes.Max()), s_cmb(solid.bdr_attributes.Max());
  s_surf = 0;
  s_cmb = 0;
  s_surf[kSurfaceBdr - 1] = 1;
  s_cmb[kCmbBdr - 1] = 1;
  auto lf_u = MakeLinearForm(&fes_u);
  auto* fi = new VectorDomainLFIntegrator(f);
  fi->SetIntRule(&ir_vol);
  lf_u->AddDomainIntegrator(fi);
  auto* ti = new VectorBoundaryLFIntegrator(t_surf);
  ti->SetIntRule(&ir_bdr);
  lf_u->AddBoundaryIntegrator(ti, s_surf);
  if (opt.cmb_traction) {
    auto* ci = new VectorBoundaryLFIntegrator(t_cmb);
    ci->SetIntRule(&ir_bdr);
    lf_u->AddBoundaryIntegrator(ci, s_cmb);
  }
  lf_u->Assemble();

  // The potential row, on the parent: volume sources of the core and the
  // shell, flux sources on the surface and the CMB.
  const int qp = 2 * order_phi + 4;
  const IntegrationRule& irp_vol = IntRules.Get(Geometry::TETRAHEDRON, qp);
  const IntegrationRule& irp_bdr = IntRules.Get(Geometry::TRIANGLE, qp);
  FunctionCoefficient q_core([](const Vector& x) {
    return d3::potential_source_core(x.GetData());
  });
  FunctionCoefficient q_shell([](const Vector& x) {
    return d3::potential_source_shell(x.GetData());
  });
  FacetCoefficient s_1(d3::surface_source, +1.0, opt.sphere_normal);
  FacetCoefficient s_b(d3::cmb_source, -1.0, opt.sphere_normal);
  Array<int> m_core(parent.attributes.Max()), m_shell(parent.attributes.Max());
  m_core = 0;
  m_shell = 0;
  m_core[kCoreAttr - 1] = 1;
  m_shell[kShellAttr - 1] = 1;
  Array<int> p_surf(parent.bdr_attributes.Max()), p_cmb(parent.bdr_attributes.Max());
  p_surf = 0;
  p_cmb = 0;
  p_surf[kSurfaceBdr - 1] = 1;
  p_cmb[kCmbBdr - 1] = 1;
  auto lf_phi = MakeLinearForm(&fes_phi);
  auto* qc = new DomainLFIntegrator(q_core);
  qc->SetIntRule(&irp_vol);
  lf_phi->AddDomainIntegrator(qc, m_core);
  auto* qs = new DomainLFIntegrator(q_shell);
  qs->SetIntRule(&irp_vol);
  lf_phi->AddDomainIntegrator(qs, m_shell);
  auto* si = new BoundaryLFIntegrator(s_1);
  si->SetIntRule(&irp_bdr);
  lf_phi->AddBoundaryIntegrator(si, p_surf);
  auto* bi = new BoundaryLFIntegrator(s_b);
  bi->SetIntRule(&irp_bdr);
  lf_phi->AddBoundaryIntegrator(bi, p_cmb);
  lf_phi->Assemble();

  problem.AssembleForce(0.0);
  problem.AddForce(*lf_u);
  problem.AddPotentialForce(*lf_phi);
  Vector c;
  bool centre;
  std::vector<int> wall_node;
  problem.LevelBorderGrid(0, c, centre, wall_node);
  MFEM_VERIFY(centre && wall_node.size() == 1 && wall_node[0] == c.Size() - 1,
              "a fluid core: a centre and one outer wall");
  const BorderData bd = IntegrateBorderData(c, opt.strong_border);
  if (opt.border_sources) {
    problem.AddLevelBorderForce(0, bd.rU, bd.rs, bd.rnu, bd.rlambda);
  }

  Results res;
  {
    // The border rows at the exact solution: y* the nodal U*, s*, nu*
    // and lambda*, x* the interpolants of u* and phi*.
    const AdGIA::LevelBorder& L = problem.LevelBorderData(0);
    Vector y(L.size);
    for (int k = 0; k <= L.n; k++) {
      if (!(L.centre && k == 0)) {
        y[L.oU + L.UIndex(k)] = d3::border_U(c[k]);
      }
      y[L.os + k] = d3::border_s(c[k]);
      y[L.onu + k] = d3::border_nu(c[k]);
    }
    y[L.ol] = kLambda;
    Rigid none;
    ExactPotential phi_star_c(none);
    auto phi_star = MakeGridFunction(&fes_phi);
    phi_star->ProjectCoefficient(phi_star_c);
    VectorFunctionCoefficient u_c(3, [](const Vector& x, Vector& v) {
      v.SetSize(3);
      d3::u(x.GetData(), v.GetData());
    });
    auto u_star = MakeGridFunction(&fes_u);
    u_star->ProjectCoefficient(u_c);
    Vector pt, ut;
    phi_star->GetTrueDofs(pt);
    u_star->GetTrueDofs(ut);
    Vector res_v(L.size), rhs(L.size);
    L.Db.Mult(y, res_v);
    rhs = 0.0;
    for (int k = 0; k <= L.n; k++) {
      if (!(L.centre && k == 0)) {
        rhs[L.oU + L.UIndex(k)] = bd.rU[k];
      }
      rhs[L.os + k] = bd.rs[k];
      rhs[L.onu + k] = bd.rnu[k];
      res_v[L.onu + k] += Dot(fes_phi, L.nu_phi[k], pt);
    }
    rhs[L.ol] = bd.rlambda[0];
    res_v[L.ol] += Dot(fes_u, L.wall_u[0], ut);
    res_v -= rhs;
    auto group = [&](int off, int len) {
      double a = 0.0, b = 0.0;
      for (int j = off; j < off + len; j++) {
        a += res_v[j] * res_v[j];
        b += rhs[j] * rhs[j];
      }
      return std::sqrt(a / b);
    };
    res.res_U = group(L.oU, L.nU);
    res.res_s = group(L.os, L.n + 1);
    res.res_nu = group(L.onu, L.n + 1);
    res.res_lambda = group(L.ol, 1);
    double d2 = 0.0;
    for (int e = 0; e < L.n; e++) {
      const double r0 = e == 0 ? 0.0 : d3::level_radius(c[e]);
      const double r1 = d3::level_radius(c[e + 1]);
      const double v = 4.0 * M_PI / 3.0 * (r1 * r1 * r1 - r0 * r0 * r0);
      const double d = std::abs(L.vol[e] - v) / v;
      res.vol_max = std::max(res.vol_max, d);
      d2 += d * d;
    }
    res.vol_rms = std::sqrt(d2 / L.n);
  }
  const auto t0 = Clock::now();
  MFEM_VERIFY(problem.Solve(), "the solve failed");
  res.solve_seconds = std::chrono::duration<double>(Clock::now() - t0).count();
  res.iterations = problem.LastOuterIterations();
  res.dofs_u = GlobalTrueSize(fes_u);
  res.dofs_phi = GlobalTrueSize(fes_phi);
  res.c_lo = c[0];
  res.c_hi = c[c.Size() - 1];

  // The rigid part of u_h - I_h u* on the discrete rigid modes.
  VectorFunctionCoefficient u_ex(3, [](const Vector& x, Vector& v) {
    v.SetSize(3);
    d3::u(x.GetData(), v.GetData());
  });
  auto u_star = MakeGridFunction(&fes_u);
  u_star->ProjectCoefficient(u_ex);
  const GridFunction& uh = problem.Displacement();
  Vector e_t, us_t;
  uh.GetTrueDofs(e_t);
  u_star->GetTrueDofs(us_t);
  e_t -= us_t;
  std::vector<Vector> modes(6);
  for (int k = 0; k < 6; k++) {
    VectorFunctionCoefficient mc(3, [k](const Vector& x, Vector& v) {
      v.SetSize(3);
      v = 0.0;
      if (k < 3) {
        v[k] = 1.0;
      } else {
        const int a = k - 3, i = (a + 1) % 3, j = (a + 2) % 3;
        v[i] = -x[j];
        v[j] = x[i];
      }
    });
    auto m = MakeGridFunction(&fes_u);
    m->ProjectCoefficient(mc);
    m->GetTrueDofs(modes[k]);
  }
  DenseMatrix gram(6);
  Vector rhs(6), coef(6);
  for (int i = 0; i < 6; i++) {
    rhs[i] = Dot(fes_u, modes[i], e_t);
    for (int j = 0; j < 6; j++) {
      gram(i, j) = Dot(fes_u, modes[i], modes[j]);
    }
  }
  DenseMatrixInverse(gram).Mult(rhs, coef);
  Rigid rigid;
  for (int k = 0; k < 3; k++) {
    rigid.a[k] = coef[k];
    rigid.b[k] = coef[3 + k];
  }
  Vector r_t(e_t.Size()), w_t;
  r_t = 0.0;
  for (int k = 0; k < 6; k++) {
    r_t.Add(coef[k], modes[k]);
  }
  uh.GetTrueDofs(w_t);
  w_t -= r_t;
  auto w = MakeGridFunction(&fes_u);
  w->SetFromTrueDofs(w_t);
  res.rigid = std::sqrt(Dot(fes_u, r_t, r_t) / Dot(fes_u, us_t, us_t));
  ShellErrors(*w, 2 * order + 3, res.u, res.stress);

  ExactPotential phi_ex(rigid);
  double v[2];
  ScalarL2(problem.Potential(), phi_ex, 0, 2 * order_phi + 3, v);
  res.phi = std::sqrt(v[0] / v[1]);
  ScalarL2(problem.Potential(), phi_ex, kCoreAttr, 2 * order_phi + 3, v);
  res.phi_core = std::sqrt(v[0] / v[1]);

  // The border unknowns at the grid's nodes.
  Vector cb, U, s, nu, lam;
  problem.LevelBorderSolution(0, cb, U, s, nu, lam);
  res.c = cb;
  res.U = U;
  res.s = s;
  res.nu = nu;
  NodalErrors(cb, U, d3::border_U, res.U_max, res.U_rms);
  NodalErrors(cb, s, d3::border_s, res.s_max, res.s_rms);
  NodalErrors(cb, nu, d3::border_nu, res.nu_max, res.nu_rms);
  res.U_vol = VolumeWeightedError(cb, U, d3::border_U_r);
  res.s_vol = VolumeWeightedError(cb, s, d3::border_s_r);
  res.nu_vol = VolumeWeightedError(cb, nu, d3::border_nu_r);
  res.lambda_h = lam[0];
  res.lambda = std::abs(lam[0] - kLambda) / std::abs(kLambda);

  // The orientation of the boundary elements' own normals.
  long fl, tot;
  double cnt[5];
  CountFlipped(solid, kCmbBdr, -1.0, fl, tot);
  cnt[0] = fl;
  cnt[1] = tot;
  CountFlipped(solid, kSurfaceBdr, +1.0, fl, tot);
  cnt[2] = fl;
  cnt[3] = tot;
  CountFlipped(parent, kCmbBdr, -1.0, fl, tot);
  cnt[4] = fl;
  SumOver(fes_u, cnt, 4);
  SumOver(fes_phi, cnt + 4, 1);
  res.flipped_cmb = static_cast<long>(cnt[0]);
  res.facets_cmb = static_cast<long>(cnt[1]);
  res.flipped_surface = static_cast<long>(cnt[2]);
  res.facets_surface = static_cast<long>(cnt[3]);
  res.parent_cmb_up = static_cast<long>(cnt[4]);
  return res;
}

}  // namespace manufactured_fluid
